package com.acme.reporting.service;

import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import javax.crypto.*;
import javax.crypto.spec.*;

public class ReportExportService {

    private static final String EXPORT_DIR = "/var/app/exports";
    private final RoleValidator roleValidator;
    private final AuditLogger auditLogger;
    private final ConcurrentHashMap<String, Path> activeExports = new ConcurrentHashMap<>();

    public ReportExportService(RoleValidator roleValidator, AuditLogger auditLogger) {
        this.roleValidator = roleValidator;
        this.auditLogger = auditLogger;
    }

    public ExportResult exportReport(UserContext user, ReportRequest request) throws Exception {
        // Step 1: Validate role-based access
        if (!roleValidator.hasPermission(user, "REPORT_EXPORT")) {
            auditLogger.logUnauthorized(user, "REPORT_EXPORT");
            throw new SecurityException("Insufficient permissions for report export");
        }

        // Step 2: Validate report scope against user's data access level
        DataScope allowedScope = roleValidator.getDataScope(user);
        if (!allowedScope.contains(request.getScope())) {
            auditLogger.logScopeViolation(user, request.getScope());
            throw new SecurityException("Report scope exceeds user data access level");
        }

        // Step 3: Generate report content
        byte[] reportData = generateReportContent(request);

        // Step 4: Create secure temporary file for export staging
        Path exportPath = createSecureTempFile(user, request);

        // Step 5: Encrypt and write report data
        writeEncryptedReport(exportPath, reportData, user);

        // Step 6: Register for cleanup
        activeExports.put(user.getSessionId(), exportPath);
        scheduleCleanup(user.getSessionId(), 300, TimeUnit.SECONDS);

        auditLogger.logExport(user, request, exportPath);
        return new ExportResult(exportPath.getFileName().toString(), reportData.length);
    }

    private Path createSecureTempFile(UserContext user, ReportRequest request) throws IOException {
        // Generate a unique filename using secure random
        SecureRandom random = new SecureRandom();
        byte[] nameBytes = new byte[16];
        random.nextBytes(nameBytes);
        String uniqueId = bytesToHex(nameBytes);

        String filename = String.format("report_%s_%s_%s.enc",
            user.getUserId(), request.getReportType(), uniqueId);

        // Sanitize filename components
        filename = filename.replaceAll("[^a-zA-Z0-9._-]", "_");

        Path exportDir = Paths.get(EXPORT_DIR);
        ensureDirectoryExists(exportDir);

        // Create the file with restricted permissions using platform-aware approach
        Path filePath = exportDir.resolve(filename);
        return createWithRestrictedPermissions(filePath);
    }

    private Path createWithRestrictedPermissions(Path filePath) throws IOException {
        // Create directly in the target directory with restricted permissions atomically
        Set<PosixFilePermission> perms = PosixFilePermissions.fromString("rw-------");
        FileAttribute<Set<PosixFilePermission>> attr = PosixFilePermissions.asFileAttribute(perms);

        // Files.createFile is atomic - no TOCTOU race possible
        // If file exists, it throws FileAlreadyExistsException rather than proceeding
        return Files.createFile(filePath, attr);
    }

    private void writeEncryptedReport(Path path, byte[] data, UserContext user) throws Exception {
        // Generate a cryptographically random, unique salt for this export
        byte[] salt = new byte[16];
        new SecureRandom().nextBytes(salt);

        SecretKey key = deriveUserKey(user, salt);
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        byte[] iv = new byte[12];
        new SecureRandom().nextBytes(iv);
        GCMParameterSpec spec = new GCMParameterSpec(128, iv);
        cipher.init(Cipher.ENCRYPT_MODE, key, spec);
        byte[] encrypted = cipher.doFinal(data);

        try (FileOutputStream fos = new FileOutputStream(path.toFile())) {
            // Persist the salt and IV so the report can be decrypted later
            fos.write(salt);
            fos.write(iv);
            fos.write(encrypted);
            fos.getFD().sync();
        }
    }

    private SecretKey deriveUserKey(UserContext user, byte[] salt) throws Exception {
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        KeySpec keySpec = new PBEKeySpec(user.getEncryptionSecret().toCharArray(), salt, 65536, 256);
        SecretKey tmp = factory.generateSecret(keySpec);
        return new SecretKeySpec(tmp.getEncoded(), "AES");
    }

    private byte[] generateReportContent(ReportRequest request) {
        // Simulated report generation
        return ("REPORT_DATA_" + request.getReportType() + "_" + System.currentTimeMillis()).getBytes();
    }

    private void ensureDirectoryExists(Path dir) throws IOException {
        if (!Files.exists(dir)) {
            Set<PosixFilePermission> perms = PosixFilePermissions.fromString("rwx------");
            FileAttribute<Set<PosixFilePermission>> attr = PosixFilePermissions.asFileAttribute(perms);
            Files.createDirectories(dir, attr);
        }
    }

    private void scheduleCleanup(String sessionId, long delay, TimeUnit unit) {
        ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
        scheduler.schedule(() -> {
            Path path = activeExports.remove(sessionId);
            if (path != null) {
                try { Files.deleteIfExists(path); } catch (IOException e) { /* log */ }
            }
            scheduler.shutdown();
        }, delay, unit);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}

class RoleValidator {
    public boolean hasPermission(UserContext user, String permission) {
        return user.getRoles().stream().anyMatch(r -> r.getPermissions().contains(permission));
    }
    public DataScope getDataScope(UserContext user) {
        return user.getRoles().stream()
            .map(Role::getDataScope)
            .reduce(DataScope::merge)
            .orElse(DataScope.NONE);
    }
}

class AuditLogger {
    public void logUnauthorized(UserContext user, String action) {}
    public void logScopeViolation(UserContext user, DataScope scope) {}
    public void logExport(UserContext user, ReportRequest req, Path path) {}
}

class UserContext {
    private String userId;
    private String sessionId;
    private String encryptionSecret;
    private List<Role> roles;
    public String getUserId() { return userId; }
    public String getSessionId() { return sessionId; }
    public String getEncryptionSecret() { return encryptionSecret; }
    public List<Role> getRoles() { return roles; }
}

class Role {
    private Set<String> permissions;
    private DataScope dataScope;
    public Set<String> getPermissions() { return permissions; }
    public DataScope getDataScope() { return dataScope; }
}

class DataScope {
    public static final DataScope NONE = new DataScope();
    public boolean contains(DataScope other) { return true; }
    public static DataScope merge(DataScope a, DataScope b) { return a; }
}

class ReportRequest {
    private String reportType;
    private DataScope scope;
    public String getReportType() { return reportType; }
    public DataScope getScope() { return scope; }
}

class ExportResult {
    private String filename;
    private long size;
    public ExportResult(String filename, long size) { this.filename = filename; this.size = size; }
}
